/**
 * 改造自 shadcn 原装 base-lyra button（https://ui.shadcn.com/r/styles/base-lyra/button.json，MIT）。
 * 与上游的功能差异：
 * 1. 基础类里每个 `disabled:` 变体都补一个 `data-disabled:` 变体。
 *    原因：`focusableWhenDisabled` 下 Base UI 不渲染 `disabled` 属性，只渲染 `aria-disabled` 与 `data-disabled`，上游的 `:disabled` 样式不生效。
 * 2. 动效改由 `motion` 属性选预设（ADR 0021）：按钮渲染 `data-motion`，过渡与按下的反馈由基础层的预设规则给出。
 *    基础类删掉 `transition-all` 与 `active:not-aria-[haspopup]:translate-y-px`；上游的下沉 1px 保留为预设 `sink`。
 *    `buttonVariants` 不带动效：套它的 `<a>` 没有按下反馈。
 * 此外只有格式化（分号）和一条 Biome 豁免注释，其余类名逐字保留。
 */
import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 items-center justify-center rounded-control border border-transparent bg-clip-padding text-xs font-medium whitespace-nowrap outline-none select-none focus-visible:border-ring focus-visible:ring-1 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-50 data-disabled:pointer-events-none data-disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-1 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:border-input dark:bg-input/30 dark:hover:bg-input/50",
        secondary:
          // biome-ignore lint/nursery/noTailwindArbitraryValue: 与上游逐字一致的 secondary 悬停色，非本次改造范围。
          "bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:hover:bg-destructive/30 dark:focus-visible:ring-destructive/40",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-8 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        xs: "h-6 gap-1 rounded-control px-2 text-xs has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-7 gap-1 rounded-control px-2.5 has-data-[icon=inline-end]:pr-1.5 has-data-[icon=inline-start]:pl-1.5 [&_svg:not([class*='size-'])]:size-3.5",
        lg: "h-9 gap-1.5 px-2.5 has-data-[icon=inline-end]:pr-2 has-data-[icon=inline-start]:pl-2",
        icon: "size-8",
        "icon-xs": "size-6 rounded-control [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-7 rounded-control",
        "icon-lg": "size-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

/**
 * 按钮支持的动效预设（ADR 0021）。缺省 `press`。
 * - `press`：按下缩到 97%，100ms。
 * - `sink`：Lyra 原版，按下下沉 1px。
 * - `none`：不动，颜色也直接切换。
 */
type ButtonMotion = "none" | "press" | "sink";

function Button({
  className,
  variant = "default",
  size = "default",
  motion = "press",
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants> & { motion?: ButtonMotion }) {
  return (
    <ButtonPrimitive
      data-slot="button"
      data-motion={motion}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

export { Button, type ButtonMotion, buttonVariants };
